import React, { useEffect, useMemo, useState } from "react";

const STORAGE_KEY = "listmaker.lists.v1";
const BACKEND_BASE = "http://localhost:4000";
const AUTH_CHOICE_KEY = "listmaker.authChoice.v1";

function uid() {
  return Math.random().toString(16).slice(2) + Date.now().toString(16);
}

function safeParse(json, fallback) {
  try {
    return JSON.parse(json);
  } catch {
    return fallback;
  }
}

function normalizeList(list) {
  return {
    id: String(list?.id ?? uid()),
    name: String(list?.name ?? "Untitled"),
    items: Array.isArray(list?.items) ? list.items.map((x) => String(x)) : [],
    createdAt: Number.isFinite(Number(list?.createdAt)) ? Number(list.createdAt) : Date.now(),
  };
}

function encodeSharedPayload(payload) {
  const json = JSON.stringify(payload);
  return btoa(unescape(encodeURIComponent(json)));
}

function decodeSharedPayload(encoded) {
  const json = decodeURIComponent(escape(atob(encoded)));
  return JSON.parse(json);
}

export default function App() {
  const [lists, setLists] = useState([]);
  const [selectedId, setSelectedId] = useState(null);

  const [newListName, setNewListName] = useState("");
  const [newItemText, setNewItemText] = useState("");

  const [shareStatus, setShareStatus] = useState("");

  // Auth choice gating (must choose FIRST)
  // Values: null | "google" | "none"
  const [authChoice, setAuthChoice] = useState(null);

  useEffect(() => {
    const raw = localStorage.getItem(AUTH_CHOICE_KEY);
    if (!raw) return;
    if (raw === "google" || raw === "none") setAuthChoice(raw);
  }, []);

  const isAuthLocked = authChoice === null;

  function chooseGoogle() {
    localStorage.setItem(AUTH_CHOICE_KEY, "google");
    setAuthChoice("google");
    setShareStatus("");

    // If we were redirected back from OAuth, keep it.
    // Otherwise, user can click “Connect & Import Today” in the Google area below.
  }

  function chooseNone() {
    localStorage.setItem(AUTH_CHOICE_KEY, "none");
    setAuthChoice("none");
    setShareStatus("");
  }

  function SignInGate() {
    // Must choose FIRST before showing list creation/editing.
    return (
      <div
        style={{
          position: "fixed",
          inset: 0,
          background: "rgba(0,0,0,0.45)",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          padding: 16,
          zIndex: 9999,
        }}
      >
        <div style={{ background: "white", borderRadius: 16, padding: 20, maxWidth: 520, width: "100%" }}>
          <h2 style={{ marginTop: 0 }}>Choose an option</h2>
          <p style={{ opacity: 0.8 }}>
            To keep your lists private on your device, you can continue without signing in. If you sign in,
            you can import today’s Google Calendar events.
          </p>

          <div style={{ display: "flex", gap: 12, marginTop: 16, flexWrap: "wrap" }}>
            <button
              onClick={chooseGoogle}
              style={{
                padding: "12px 14px",
                borderRadius: 12,
                border: "none",
                background: "#2563eb",
                color: "white",
                cursor: "pointer",
                fontWeight: 700,
              }}
            >
              Sign in with Google
            </button>

            <button
              onClick={chooseNone}
              style={{
                padding: "12px 14px",
                borderRadius: 12,
                border: "1px solid #e5e7eb",
                background: "white",
                color: "#111827",
                cursor: "pointer",
                fontWeight: 700,
              }}
            >
              Continue without sign-in
            </button>
          </div>

          <div style={{ marginTop: 14, fontSize: 12, opacity: 0.7 }}>
            {authChoice === "none" ? "Google Calendar import is disabled." : ""}
          </div>
        </div>
      </div>
    );
  }

  // Load from localStorage


  useEffect(() => {
    const raw = localStorage.getItem(STORAGE_KEY);
    if (!raw) return;

    const parsed = safeParse(raw, []);
    const normalized = Array.isArray(parsed) ? parsed.map(normalizeList) : [];
    setLists(normalized);

    if (normalized.length > 0) {
      setSelectedId(normalized[0].id);
    }
  }, []);

  // Handle shared payload in URL (if present)
  useEffect(() => {
    const url = new URL(window.location.href);
    const share = url.searchParams.get("share");
    if (!share) return;

    try {
      const payload = decodeSharedPayload(share);
      // Expected payload: { name, items } (or full list)
      const listFromShare = normalizeList(payload?.list ?? payload);

      setLists((prev) => {
        // If same name/id exists, still add as new instance with new id.
        const incoming = { ...listFromShare, id: uid(), createdAt: Date.now() };
        return [incoming, ...prev];
      });
      setSelectedId((prev) => prev); // keep selection if possible
      setShareStatus("Shared list received and saved locally ✅");

      // Clean URL
      url.searchParams.delete("share");
      window.history.replaceState({}, document.title, url.toString());
    } catch {
      setShareStatus("Could not import shared list. Link may be invalid.");
    }
  }, []);

  // Persist lists
  useEffect(() => {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(lists));
  }, [lists]);

  // If backend redirected back with googleConnected=1, fetch today events
  useEffect(() => {
    const url = new URL(window.location.href);
    const connected = url.searchParams.get("googleConnected");
    if (!connected) return;

    async function run() {
      try {
        setShareStatus("Loading today’s Google Calendar events...");
        const userId = "demo";
        const resp = await fetch(`${BACKEND_BASE}/api/calendar/today`, {
          headers: { "x-user-id": userId },
        });

        if (!resp.ok) {
          const msg = await resp.text();
          setShareStatus(`Failed to load calendar: ${msg}`);
          return;
        }

        const data = await resp.json();
        const events = Array.isArray(data?.events) ? data.events : [];

        const listName = new Date().toLocaleDateString([], { weekday: "long", year: "numeric", month: "short", day: "numeric" });
        const items = events.map((e) => (e.start ? `${e.start} - ${e.summary}` : e.summary));

        const list = { id: uid(), name: `Today: ${listName}`, items, createdAt: Date.now() };
        setLists((prev) => [list, ...prev]);
        setSelectedId(list.id);
        setShareStatus(`Added ${items.length} events to a local list ✅`);

        url.searchParams.delete("googleConnected");
        window.history.replaceState({}, document.title, url.toString());
      } catch {
        setShareStatus("Could not load Google Calendar events.");
      }
    }

    run();
  }, []);


  const selectedList = useMemo(() => {
    return lists.find((l) => l.id === selectedId) ?? null;
  }, [lists, selectedId]);

  function createList() {
    const name = newListName.trim() || "Untitled";
    const list = {
      id: uid(),
      name,
      items: [],
      createdAt: Date.now(),
    };

    setLists((prev) => [list, ...prev]);
    setSelectedId(list.id);
    setNewListName("");
  }

  function deleteSelectedList() {
    if (!selectedList) return;

    setLists((prev) => prev.filter((l) => l.id !== selectedList.id));
    setSelectedId(null);
    setNewItemText("");
  }

  function addItem() {
    if (!selectedList) return;
    const text = newItemText.trim();
    if (!text) return;

    setLists((prev) =>
      prev.map((l) => {
        if (l.id !== selectedList.id) return l;
        return { ...l, items: [text, ...l.items] };
      })
    );

    setNewItemText("");
  }

  function deleteItem(index) {
    if (!selectedList) return;
    setLists((prev) =>
      prev.map((l) => {
        if (l.id !== selectedList.id) return l;
        return { ...l, items: l.items.filter((_, i) => i !== index) };
      })
    );
  }



  function exportSelectedList() {
    if (!selectedList) return;

    const exportPayload = {
      version: 1,
      exportedAt: Date.now(),
      list: {
        name: selectedList.name,
        items: selectedList.items,
        createdAt: selectedList.createdAt,
      },
    };

    const blob = new Blob([JSON.stringify(exportPayload, null, 2)], { type: "application/json" });
    const url = URL.createObjectURL(blob);

    const a = document.createElement("a");
    a.href = url;
    a.download = `${selectedList.name.replace(/[^a-z0-9\- _]/gi, "").trim() || "list"}.json`;
    document.body.appendChild(a);
    a.click();
    a.remove();
    URL.revokeObjectURL(url);

    setShareStatus("List downloaded as JSON ✅");
  }

  function importListFromFile(file) {
    if (!file) return;

    const reader = new FileReader();
    reader.onload = () => {
      try {
        const text = String(reader.result ?? "");
        const parsed = JSON.parse(text);
        const maybeList = parsed?.list ?? parsed;
        const normalized = normalizeList(maybeList);

        const incoming = {
          ...normalized,
          id: uid(),
          createdAt: Date.now(),
        };

        setLists((prev) => [incoming, ...prev]);
        setSelectedId(incoming.id);
        setShareStatus("List imported from file ✅");
      } catch {
        setShareStatus("Could not import file. Make sure it’s a valid export JSON.");
      }
    };

    reader.onerror = () => {
      setShareStatus("Could not read file.");
    };

    reader.readAsText(file);
  }

  async function fetchTodayFromGoogleAndCreateList() {
    try {
      setShareStatus("Starting Google Calendar login...");

      // Ensure we send an id for the OAuth state.
      const userId = "demo";

      const connectRes = await fetch(`${BACKEND_BASE}/api/google/connect`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ userId }),
      });

      if (!connectRes.ok) {
        const msg = await connectRes.text();
        setShareStatus(`Google connect failed: ${msg}`);
        return;
      }

      const { url } = await connectRes.json();
      if (!url) {
        setShareStatus("Google connect failed: missing auth URL.");
        return;
      }

      // Redirect to Google OAuth flow via backend.
      // After OAuth, backend redirects back with googleConnected=1.
      window.location.href = url;
    } catch {
      setShareStatus("Could not start Google Calendar connection.");
    }
  }


  function shareSelectedList() {
    if (!selectedList) return;
    const payload = { list: { name: selectedList.name, items: selectedList.items } };
    const encoded = encodeSharedPayload(payload);


    const url = new URL(window.location.href);
    url.searchParams.set("share", encoded);

    const shareUrl = url.toString();

    // Clipboard if available
    if (navigator.clipboard?.writeText) {
      navigator.clipboard
        .writeText(shareUrl)
        .then(() => setShareStatus("Share link copied ✅"))
        .catch(() => setShareStatus("Share link ready (copy manually)."));
    } else {
      setShareStatus("Share link ready (copy manually).");
    }

    // Also provide a prompt fallback
    window.prompt("Copy this share link:", shareUrl);
  }


  return (
    <div style={{ fontFamily: "system-ui, -apple-system, Segoe UI, Roboto, sans-serif", maxWidth: 860, margin: "24px auto", padding: 16 }}>
      <h1 style={{ marginTop: 0 }}>List Maker</h1>
      <p style={{ opacity: 0.8, marginTop: -8 }}>
        Create lists, save locally, and share via a link that imports into other phones with the app.
      </p>

      {shareStatus ? (
        <div style={{ background: "#f3f4f6", borderRadius: 10, padding: 12, margin: "16px 0" }}>
          {shareStatus}
        </div>
      ) : null}

      <div style={{ display: "grid", gridTemplateColumns: "320px 1fr", gap: 16 }}>
        <section style={{ border: "1px solid #e5e7eb", borderRadius: 12, padding: 12 }}>
          <h2 style={{ fontSize: 16, margin: "4px 0 10px" }}>Your lists</h2>

          <div style={{ display: "flex", gap: 8 }}>
            <input
              value={newListName}
              onChange={(e) => setNewListName(e.target.value)}
              placeholder="List name"
              style={{ flex: 1, padding: 10, borderRadius: 10, border: "1px solid #d1d5db" }}
            />
            <button
              onClick={createList}
              style={{ padding: "10px 12px", borderRadius: 10, border: "none", background: "#111827", color: "white", cursor: "pointer" }}
            >
              Add
            </button>
          </div>

          <div style={{ marginTop: 12, display: "flex", flexDirection: "column", gap: 8 }}>
            {lists.length === 0 ? (
              <div style={{ opacity: 0.7, fontSize: 14 }}>No lists yet. Create one above.</div>
            ) : (
              lists.map((l) => (
                <button
                  key={l.id}
                  onClick={() => setSelectedId(l.id)}
                  style={{
                    textAlign: "left",
                    padding: 10,
                    borderRadius: 10,
                    border: selectedId === l.id ? "2px solid #2563eb" : "1px solid #e5e7eb",
                    background: selectedId === l.id ? "#eff6ff" : "white",
                    cursor: "pointer",
                  }}
                >
                  <div style={{ fontWeight: 700 }}>{l.name}</div>
                  <div style={{ fontSize: 12, opacity: 0.7 }}>{l.items.length} items</div>
                </button>
              ))
            )}
          </div>


        </section>

        <section style={{ border: "1px solid #e5e7eb", borderRadius: 12, padding: 12 }}>
      <h2 style={{ fontSize: 16, margin: "4px 0 10px" }}>List details</h2>

          {!selectedList ? (
            <div style={{ opacity: 0.7 }}>Select a list to view/edit.</div>
          ) : (
            <>
              <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", gap: 12 }}>
                <div>
                  <div style={{ fontSize: 20, fontWeight: 800 }}>{selectedList.name}</div>
                  <div style={{ opacity: 0.7, marginTop: 4, fontSize: 13 }}>
                    Created {new Date(selectedList.createdAt).toLocaleString()}
                  </div>
                </div>

                <div style={{ display: "flex", flexDirection: "column", gap: 8, alignItems: "flex-end" }}>
                  <button
                    onClick={fetchTodayFromGoogleAndCreateList}
                    style={{ padding: "10px 12px", borderRadius: 10, border: "none", background: "#2563eb", color: "white", cursor: "pointer" }}
                    title="Connect Google and import today's events into a local list"
                  >
                    Connect & Import Today
                  </button>


                  <button
                    onClick={shareSelectedList}
                    style={{ padding: "10px 12px", borderRadius: 10, border: "none", background: "#0f766e", color: "white", cursor: "pointer" }}
                  >
                    Share list
                  </button>


                  <button
                    onClick={exportSelectedList}
                    style={{ padding: "10px 12px", borderRadius: 10, border: "1px solid #e5e7eb", background: "white", color: "#111827", cursor: "pointer" }}
                  >
                    Download JSON
                  </button>

                  <label
                    style={{ padding: "10px 12px", borderRadius: 10, border: "1px dashed #6b7280", background: "white", color: "#111827", cursor: "pointer", textAlign: "center" }}
                    title="Upload a previously downloaded list JSON file"
                  >
                    Upload JSON
                    <input
                      type="file"
                      accept="application/json,.json"
                      style={{ display: "none" }}
                      onChange={(e) => importListFromFile(e.target.files?.[0])}
                    />
                  </label>

                  <button
                    onClick={deleteSelectedList}
                    style={{ padding: "10px 12px", borderRadius: 10, border: "1px solid #ef4444", background: "#fff", color: "#dc2626", cursor: "pointer" }}
                  >
                    Delete list
                  </button>
                </div>

              </div>

              <div style={{ marginTop: 16, display: "flex", gap: 8 }}>
                <input
                  value={newItemText}
                  onChange={(e) => setNewItemText(e.target.value)}
                  placeholder="Add an item"
                  style={{ flex: 1, padding: 10, borderRadius: 10, border: "1px solid #d1d5db" }}
                  onKeyDown={(e) => {
                    if (e.key === "Enter") addItem();
                  }}
                />
                <button
                  onClick={addItem}
                  style={{ padding: "10px 12px", borderRadius: 10, border: "none", background: "#111827", color: "white", cursor: "pointer" }}
                >
                  Add item
                </button>
              </div>

              <div style={{ marginTop: 12, display: "flex", flexDirection: "column", gap: 8 }}>
                {selectedList.items.length === 0 ? (
                  <div style={{ opacity: 0.7, fontSize: 14 }}>No items yet.</div>
                ) : (
                  selectedList.items.map((item, idx) => (
                    <div key={idx} style={{ display: "flex", justifyContent: "space-between", alignItems: "center", gap: 10, border: "1px solid #e5e7eb", borderRadius: 10, padding: 10 }}>
                      <div style={{ fontWeight: 600 }}>{item}</div>
                      <button
                        onClick={() => deleteItem(idx)}
                        style={{ padding: "8px 10px", borderRadius: 10, border: "1px solid #e5e7eb", background: "white", cursor: "pointer" }}
                      >
                        Remove
                      </button>
                    </div>
                  ))
                )}
              </div>
            </>
          )}
        </section>
      </div>

      <footer style={{ marginTop: 18, opacity: 0.7, fontSize: 12 }}>
        Data is stored only on your device (localStorage). Share uses a URL import payload.
      </footer>
    </div>
  );
}
